    "A year ago you shared a selfie with {parent}.": ["एक साल पहले आपने {parent} के साथ सेल्फ़ी साझा की थी।", "এক বছর আগে আপনি {parent}-এর সাথে সেলফি শেয়ার করেছিলেন।", "قبل عام شاركت صورة مع {parent}.", "Hace un año compartiste un selfi con {parent}.", "Il y a un an, vous avez partagé un selfie avec {parent}."],
    "{n} years ago you shared a selfie with {parent}.": ["{n} साल पहले आपने {parent} के साथ सेल्फ़ी साझा की थी।", "{n} বছর আগে আপনি {parent}-এর সাথে সেলফি শেয়ার করেছিলেন।", "قبل {n} سنوات شاركت صورة مع {parent}.", "Hace {n} años compartiste un selfi con {parent}.", "Il y a {n} ans, vous avez partagé un selfie avec {parent}."],
