    "Add my selfie with {name}": ["{name} के साथ मेरी सेल्फ़ी जोड़ें", "{name}-এর সঙ্গে আমার সেলফি যোগ করুন", "أضف صورتي مع {name}", "Añadir mi selfie con {name}", "Ajouter mon selfie avec {name}"],
