    "Please tick all three boxes to continue.": ["आगे बढ़ने के लिए तीनों बॉक्स पर टिक करें।", "এগোতে তিনটি বাক্সেই টিক দিন।", "يرجى تحديد المربعات الثلاثة للمتابعة.", "Marca las tres casillas para continuar.", "Cochez les trois cases pour continuer."],
    "Submit selfie": ["सेल्फी भेजें", "সেলফি জমা দিন", "أرسل الصورة", "Enviar selfie", "Envoyer le selfie"],
    "Sending…": ["भेजा जा रहा है…", "পাঠানো হচ্ছে…", "جارٍ الإرسال…", "Enviando…", "Envoi…"],
    "Thank you,": ["धन्यवाद,", "ধন্যবাদ,", "شكرًا،", "¡Gracias,", "Merci,"],
    "Your selfie is in our review queue. It usually appears in the gallery within 48 hours.": ["आपकी सेल्फी जाँच के लिए कतार में है। आमतौर पर यह 48 घंटों में गैलरी में दिखती है।", "আপনার সেলফি যাচাইয়ের অপেক্ষায় আছে। সাধারণত ৪৮ ঘণ্টার মধ্যে গ্যালারিতে দেখা যায়।", "صورتك في قائمة المراجعة. تظهر عادةً في المعرض خلال 48 ساعة.", "Tu selfie está en revisión. Suele aparecer en la galería en 48 horas.", "Votre selfie est en cours de vérification. Il apparaît généralement sous 48 heures."],
    "Reference:": ["संदर्भ संख्या:", "রেফারেন্স:", "الرقم المرجعي:", "Referencia:", "Référence :"],
    "Make a frame": ["फ़्रेम बनाएं", "ফ্রেম তৈরি করুন", "اصنع إطارًا", "Crear un marco", "Créer un cadre"],
    "Share another": ["एक और साझा करें", "আরেকটি শেয়ার করুন", "شارك صورة أخرى", "Compartir otro", "En partager un autre"],
    "Selected photo preview": ["चुनी गई फ़ोटो की झलक", "নির্বাচিত ছবির ঝলক", "معاينة الصورة المختارة", "Vista previa de la foto", "Aperçu de la photo"],
    "Original photo preview": ["मूल फ़ोटो की झलक", "আসল ছবির ঝলক", "معاينة الصورة الأصلية", "Vista previa de la foto original", "Aperçu de la photo d'origine"],
    "Remove photo": ["फ़ोटो हटाएं", "ছবি সরান", "إزالة الصورة", "Quitar foto", "Retirer la photo"],
    "Please add a photo to continue.": ["आगे बढ़ने के लिए फ़ोटो जोड़ें।", "এগোতে একটি ছবি যোগ করুন।", "يرجى إضافة صورة للمتابعة.", "Añade una foto para continuar.", "Ajoutez une photo pour continuer."],
    "Please choose a JPG, PNG or WebP image.": ["कृपया JPG, PNG या WebP फ़ोटो चुनें।", "অনুগ্রহ করে JPG, PNG বা WebP ছবি বাছুন।", "يرجى اختيار صورة JPG أو PNG أو WebP.", "Elige una imagen JPG, PNG o WebP.", "Choisissez une image JPG, PNG ou WebP."],
    "That photo is larger than 10 MB. Please pick a smaller one.": ["यह फ़ोटो 10 MB से बड़ी है। कृपया छोटी फ़ोटो चुनें।", "ছবিটি ১০ MB-এর বেশি। ছোট একটি ছবি বাছুন।", "الصورة أكبر من 10 ميغابايت. يرجى اختيار صورة أصغر.", "La foto supera los 10 MB. Elige una más pequeña.", "Cette photo dépasse 10 Mo. Choisissez-en une plus légère."],
    "That photo is very small. Please use one at least 300 px wide.": ["यह फ़ोटो बहुत छोटी है। कम से कम 300 px चौड़ी फ़ोटो लगाएं।", "ছবিটি খুব ছোট। অন্তত ৩০০ px চওড়া ছবি দিন।", "الصورة صغيرة جدًا. استخدم صورة بعرض 300 بكسل على الأقل.", "La foto es muy pequeña. Usa una de al menos 300 px de ancho.", "Cette photo est trop petite. Utilisez-en une d'au moins 300 px de large."],
    "We couldn't read that image. Please try another.": ["यह फ़ोटो खुल नहीं पाई। कृपया दूसरी आज़माएं।", "ছবিটি পড়া গেল না। অন্য একটি চেষ্টা করুন।", "تعذّرت قراءة الصورة. يرجى تجربة أخرى.", "No pudimos leer esa imagen. Prueba con otra.", "Impossible de lire cette image. Essayez-en une autre."],
    "Something went wrong sending your selfie. Please try again.": ["सेल्फी भेजने में दिक्कत हुई। कृपया दोबारा कोशिश करें।", "সেলফি পাঠাতে সমস্যা হয়েছে। আবার চেষ্টা করুন।", "حدث خطأ أثناء إرسال صورتك. يرجى المحاولة مرة أخرى.", "Algo falló al enviar tu selfie. Inténtalo de nuevo.", "Un problème est survenu lors de l'envoi. Réessayez."],
    "Copy this prompt": ["यह प्रॉम्प्ट कॉपी करें", "এই প্রম্পটটি কপি করুন", "انسخ هذا الأمر", "Copia este prompt", "Copiez ce prompt"],

    // ----- Video -----
    "Share a photo or a video": ["फ़ोटो या वीडियो साझा करें", "ছবি বা ভিডিও শেয়ার করুন", "شارك صورة أو فيديو", "Comparte una foto o un vídeo", "Partagez une photo ou une vidéo"],
